def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    last_me, last_opp = history[-1]

    if n >= 99:
        return 'D'

    if n < 3:
        return 'C' if last_opp == 'C' else 'D'

    if opp_d == 0:
        if n >= 90 and rng.random() < 0.15:
            return 'D'
        return 'C'

    recent8 = opp[-8:]
    rec_c8 = recent8.count('C')
    rec_d8 = len(recent8) - rec_c8

    if opp_c == 0:
        return 'D'

    if opp_d * 5 > n * 4:
        if last_opp == 'C' and rng.random() < 0.12:
            return 'C'
        return 'D'

    if rec_d8 >= 6:
        if last_opp == 'C' and n > 12 and rng.random() < 0.2:
            return 'C'
        return 'D'

    if rec_c8 >= 7:
        if n >= 20 and rng.random() < 0.06:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if last_me == 'D':
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        if n >= 6 and opp[-6:].count('D') >= 3:
            return 'D'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    if opp_c * 100 < n * 50:
        if rng.random() < 0.35:
            return 'D'
        return 'C'

    if rng.random() < 0.07:
        return 'D'
    return 'C'
